import itertools

class ExclusivityProbesCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom
        self.known_particles = []
        self.potential_positions = []

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def generate_initial_positions(self, dimension):
        for p in itertools.product([0, 1], repeat=dimension):
            self.potential_positions.append(list(p))

    def update_potential_positions(self, new_particle, distance, dimension):
        self.potential_positions = [p for p in self.potential_positions if self.hamming_distance(p, new_particle) >= distance]

    def hamming_distance(self, x, y):
        return sum(el1!= el2 for el1, el2 in zip(x, y))

    def select_next_guess(self):
        if not self.potential_positions:
            return None
        return self.potential_positions[0]

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        dimension = data['dimension']
        num_particles = data['num_particles']
        distance = data['distance']
        prev_guess = data['guess']
        is_particle = data['is_particle']
        next_guess = None

        if not self.potential_positions:
            self.generate_initial_positions(dimension)

        if prev_guess is not None and is_particle:
            self.known_particles.append(prev_guess)
            self.update_potential_positions(prev_guess, distance, dimension)

        next_guess = self.select_next_guess()

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=next_guess, type='custom')]
        )
